function extract(win) {
  var out = [];
  var seen = {};

  function num(v) {
    var n = typeof v === 'number' ? v : parseFloat(String(v == null ? '' : v).replace(/[^0-9.]/g, ''));
    return isFinite(n) ? n : null;
  }

  function fromCapturedJson() {
    var caps = win.__cap || [];
    for (var i = 0; i < caps.length; i++) {
      var c = caps[i];
      if (!c || !c.body) continue;
      var j;
      try { j = JSON.parse(c.body); } catch (e) { continue; }
      var prods = j && j.data && j.data.My && j.data.My.products;
      if (!prods || !Array.isArray(prods.results) || prods.results.length === 0) continue;

      for (var k = 0; k < prods.results.length; k++) {
        var r = prods.results[k];
        if (!r || !r.productName || seen[r.sku]) continue;
        seen[r.sku] = true;
        var v = r.variants && r.variants[0];
        var vp = v && v.variantPrice;
        var price = vp ? num(vp.sellingPrice) : null;
        if (price === null) throw new Error('Missing price for product: ' + r.productName);
        var unit = null;
        if (vp && vp.cupPrice != null && vp.cupUnit) {
          unit = '$' + Number(vp.cupPrice).toFixed(2) + '/' + vp.cupUnit;
        }
        out.push({ name: r.productName, price: price, unit_price: unit });
      }
      if (out.length) return out;
    }
    return null;
  }

  function fromDom() {
    var doc = win.document;
    var tiles = doc.querySelectorAll('.product-grid_productTileCell__QRTtz');
    var res = [];
    for (var i = 0; i < tiles.length; i++) {
      var t = tiles[i];
      var nameEl = t.querySelector('a.product-tile_description__jfRLo');
      if (!nameEl) continue; // skeleton/ghost tile
      var name = nameEl.textContent.trim();
      if (seen[name]) continue;
      seen[name] = true;
      var priceEl = t.querySelector('.product-price_value__ahw_i');
      var price = priceEl ? num(priceEl.textContent) : null;
      if (price === null) throw new Error('Missing price for product: ' + name);
      var cupEl = t.querySelector('.product-cup-price_price__JTQuN > div');
      var unit = cupEl ? cupEl.textContent.replace(/\s+/g, '') : null;
      if (unit && unit.indexOf('/') < 0) unit = null;
      res.push({ name: name, price: price, unit_price: unit || null });
    }
    return res;
  }

  var fromJsonRes = fromCapturedJson();
  if (fromJsonRes && fromJsonRes.length) return fromJsonRes;

  var domRes = fromDom();
  if (domRes.length) return domRes;

  throw new Error('No product listing data found on page');
}

function extract(win) {
  const caps = (win.__cap || []).filter(function (e) {
    return e && typeof e.url === 'string' && e.url.indexOf('/search/paginated/products') !== -1 && e.body;
  });
  if (!caps.length) throw new Error('captured product search JSON is missing');

  const seen = {};
  const out = [];

  for (const e of caps) {
    let data;
    try { data = JSON.parse(e.body); } catch (err) { continue; }
    const list = Array.isArray(data && data.products) ? data.products : [];

    for (const p of list) {
      if (!p || !p.productId || seen[p.productId]) continue;
      seen[p.productId] = true;

      const sp = p.singlePrice;
      if (!sp || typeof sp.price !== 'number') {
        throw new Error('missing shelf price for product ' + p.productId);
      }

      const name = (p.name || '').trim();
      const brand = (p.brand || '').trim();
      let full = (brand && name.indexOf(brand) !== 0) ? (brand + ' ' + name) : name;
      if (p.displayName) full = (full + ' ' + p.displayName).trim();
      if (!full) throw new Error('missing name for product ' + p.productId);

      const cp = sp.comparativePrice;
      let unitPrice = null;
      if (cp && typeof cp.pricePerUnit === 'number' && cp.unitQuantity && cp.unitQuantityUom) {
        unitPrice = '$' + (cp.pricePerUnit / 100).toFixed(2) + '/' + cp.unitQuantity + cp.unitQuantityUom;
      }

      out.push({
        name: full,
        price: Math.round(sp.price) / 100,
        unit_price: unitPrice
      });
    }
  }

  if (!out.length) throw new Error('no products found in captured JSON');
  return out;
}

function extract(win) {
  function fromCapture() {
    var cap = win.__cap || [];
    for (var i = 0; i < cap.length; i++) {
      var c = cap[i];
      if (!c || !c.body || typeof c.url !== 'string') continue;
      if (c.url.indexOf('api-prod.newworld.co.nz') === -1 || c.url.indexOf('/search/') === -1) continue;
      var data;
      try { data = JSON.parse(c.body); } catch (e) { continue; }
      if (!data || !Array.isArray(data.products) || data.products.length === 0) continue;
      var items = [];
      for (var j = 0; j < data.products.length; j++) {
        var p = data.products[j];
        if (!p || !p.singlePrice || typeof p.singlePrice.price !== 'number') continue;
        var name = [p.brand, p.name, p.displayName]
          .filter(function (s) { return s && String(s).trim(); })
          .join(' ')
          .replace(/\s+/g, ' ')
          .trim();
        var cp = p.singlePrice.comparativePrice;
        var unit = null;
        if (cp && typeof cp.pricePerUnit === 'number' && cp.unitQuantityUom) {
          unit = '$' + (cp.pricePerUnit / 100).toFixed(2) + '/' +
            (cp.unitQuantity || 1) + cp.unitQuantityUom;
        }
        items.push({
          name: name,
          price: Math.round(p.singlePrice.price) / 100,
          unit_price: unit
        });
      }
      if (items.length) return items;
    }
    return null;
  }

  function fromDom() {
    var doc = win.document;
    var all = doc.querySelectorAll('[data-testid]');
    var items = [];
    for (var i = 0; i < all.length; i++) {
      var card = all[i];
      if (!/^product-\d+/.test(card.getAttribute('data-testid'))) continue;
      var titleEl = card.querySelector('[data-testid="product-title"]');
      if (!titleEl) continue;
      var subEl = card.querySelector('[data-testid="product-subtitle"]');
      var dollarsEl = card.querySelector('[data-testid="price-dollars"]');
      var centsEl = card.querySelector('[data-testid="price-cents"]');
      var unitEl = card.querySelector('[data-testid="non-promo-unit-price"]');
      if (!dollarsEl) continue;
      var dollars = dollarsEl.textContent.replace(/[^\d]/g, '');
      var cents = centsEl ? centsEl.textContent.replace(/[^\d]/g, '') : '00';
      var price = parseFloat(dollars + '.' + (cents || '00'));
      if (isNaN(price)) continue;
      var title = titleEl.textContent.replace(/\s+/g, ' ').trim();
      var sub = subEl ? subEl.textContent.replace(/\s+/g, ' ').trim() : '';
      items.push({
        name: (title + (sub ? ' ' + sub : '')).trim(),
        price: price,
        unit_price: unitEl && unitEl.textContent.trim() ? unitEl.textContent.trim() : null
      });
    }
    return items.length ? items : null;
  }

  var result = fromCapture() || fromDom();
  if (!result) {
    throw new Error('no product listing found in captured JSON or DOM');
  }
  return result;
}

function extract(win) {
  var doc = win.document;
  var tiles = doc.querySelectorAll('[class*="product-tile_component_product-tile__"]');
  var products = [];

  function text(el) {
    return el ? (el.textContent || '').replace(/\s+/g, ' ').trim() : '';
  }

  for (var i = 0; i < tiles.length; i++) {
    var tile = tiles[i];

    // Skip non-product tiles (e.g. content cards) that have no lead price.
    var priceEl = tile.querySelector('[class*="product-tile-price-info_lead-price-value"]');
    var nameEl = tile.querySelector('[class*="product-tile-name_display-name-truncated"]');
    if (!priceEl || !nameEl) continue;

    var priceText = text(priceEl).replace(/[^0-9.]/g, '');
    var price = parseFloat(priceText);
    if (isNaN(price)) continue;

    var name = text(nameEl);
    if (!name) continue;

    var cupEl = tile.querySelector('[class*="product-tile-price-info_cup-price"]');
    var unitPrice = cupEl ? text(cupEl).replace(/\s*\/\s*/, '/') : null;
    if (!unitPrice) unitPrice = null;

    products.push({
      name: name,
      price: price,
      unit_price: unitPrice
    });
  }

  if (products.length === 0) {
    throw new Error('No product tiles with name and price found on listing page');
  }

  return products;
}

function extract(win) {
  const doc = win.document;

  // Product tiles only. Ad/CTA tiles (data-testid="ad-tile-aem") are excluded.
  const tiles = Array.from(doc.querySelectorAll('section[data-testid="product-tile"]'));
  if (tiles.length === 0) {
    throw new Error('no product tiles found on listing page');
  }

  const parsePrice = (text) => {
    const m = String(text || '').replace(/,/g, '').match(/\d+(?:\.\d+)?/);
    return m ? parseFloat(m[0]) : NaN;
  };

  const results = tiles.map((tile, i) => {
    const titleEl = tile.querySelector('h2.product__title');
    const name = titleEl ? titleEl.textContent.replace(/\s+/g, ' ').trim() : '';
    if (!name) {
      throw new Error('product tile ' + i + ' is missing a name');
    }

    const priceEl = tile.querySelector('[data-testid="product-pricing"]');
    if (!priceEl) {
      throw new Error('product "' + name + '" is missing a shelf price');
    }
    const price = parsePrice(priceEl.textContent || priceEl.getAttribute('aria-label'));
    if (isNaN(price)) {
      throw new Error('product "' + name + '" has an unparseable price');
    }

    // Unit price lives in .price__calculation_method; the "| Was $x" span is excluded.
    let unit_price = null;
    const calcEl = tile.querySelector('.price__calculation_method');
    if (calcEl) {
      const raw = Array.from(calcEl.childNodes)
        .filter((n) => n.nodeType === 3)
        .map((n) => n.textContent)
        .join('')
        .replace(/\s+/g, '')
        .trim();
      unit_price = raw || null;
    }

    return { name, price, unit_price };
  });

  return results;
}

function extract(win) {
  var doc = win.document;
  var rows = doc.querySelectorAll('tr.athing.submission');
  if (!rows || rows.length === 0) {
    throw new Error('no story rows (tr.athing.submission) found on the page');
  }

  var base = (win.location && win.location.href) || undefined;
  var out = [];

  for (var i = 0; i < rows.length; i++) {
    var row = rows[i];
    var link = row.querySelector('span.titleline > a');
    if (!link) {
      throw new Error('story row ' + (row.id || i) + ' is missing its title link');
    }

    var title = (link.textContent || '').replace(/\s+/g, ' ').trim();
    var href = link.getAttribute('href') || '';
    var url;
    try {
      url = base ? new URL(href, base).href : href;
    } catch (e) {
      url = href;
    }

    // The subtext row is the sibling after the athing row; the score sits in it.
    var scoreEl = null;
    if (row.id) {
      scoreEl = doc.getElementById('score_' + row.id);
    }
    if (!scoreEl) {
      var sub = row.nextElementSibling;
      scoreEl = sub ? sub.querySelector('span.score') : null;
    }

    var points = 0;
    if (scoreEl) {
      var m = (scoreEl.textContent || '').match(/(\d[\d,]*)/);
      if (m) {
        points = parseInt(m[1].replace(/,/g, ''), 10);
      }
    }

    out.push({
      title: title,
      url: url,
      points: points
    });
  }

  return out;
}

function extract(win) {
  const doc = win.document;
  const base = win.location && win.location.href ? win.location.href : 'https://www.bbc.com/news';
  const seen = new Set();
  const results = [];

  const headlines = doc.querySelectorAll('h2[data-testid="card-headline"]');
  headlines.forEach(h2 => {
    const title = (h2.textContent || '').replace(/\s+/g, ' ').trim();
    if (!title) return;

    const anchor = h2.closest('a[href]');
    if (!anchor) return;

    let url;
    try {
      url = new URL(anchor.getAttribute('href'), base).href;
    } catch (e) {
      return;
    }

    const key = url + '|' + title;
    if (seen.has(key)) return;
    seen.add(key);

    results.push({ title, url });
  });

  if (results.length === 0) {
    throw new Error('No news headlines found on page');
  }

  return results;
}

function extract(win) {
  const doc = win.document;
  const articles = Array.from(doc.querySelectorAll('article.Box-row'));
  if (articles.length === 0) {
    throw new Error('no trending repository rows found in DOM');
  }

  const results = articles.map((article) => {
    const link = article.querySelector('h2 a[href]');
    if (!link) {
      throw new Error('repository link missing in trending row');
    }

    const href = link.getAttribute('href') || '';
    const path = href.replace(/^\/+/, '').split('?')[0].split('#')[0];
    const parts = path.split('/').filter(Boolean);
    if (parts.length < 2) {
      throw new Error('unexpected repository href: ' + href);
    }
    const title = parts[0] + '/' + parts[1];
    const url = new URL('/' + title, win.location && win.location.href ? win.location.href : 'https://github.com').href;

    const todayEl = Array.from(article.querySelectorAll('span'))
      .find((el) => /stars?\s+today/i.test(el.textContent || ''));
    if (!todayEl) {
      throw new Error('stars today missing for ' + title);
    }
    const match = todayEl.textContent.replace(/,/g, '').match(/(\d+)\s+stars?\s+today/i);
    if (!match) {
      throw new Error('could not parse stars today for ' + title);
    }
    const stars_today = parseInt(match[1], 10);

    return { title, url, stars_today };
  });

  return results;
}
